/**
 * The checkout's money core: amount arithmetic and the payment state machine.
 *
 * The arithmetic and the state machine are proved in dafny/PaymentCore.dfy (TaxBounded,
 * RegionalNeverRaises, NoRegression, CancelledAbsorbs, OnlyFromPending, PaidNeedsMoney,
 * Idempotent, RecordOnly) and compiled to ./generated by scripts/build-dafny.mjs. This file is
 * the typed boundary: it turns numbers into Dafny integers and decision codes into names, and
 * holds the currency facts Stripe imposes (minor units, limits), which are data, not proofs.
 *
 * Every amount here is an integer count of the currency's minor unit (cents, yen, fils). Nothing
 * reads a float price, and nothing here ever sees an amount from a request.
 */
import BigNumber from 'bignumber.js';
import { PaymentCore } from './generated/payment-core.js';
import type { OrderStatus } from './types';

const core = PaymentCore.__default;
const big = (n: number) => new BigNumber(n);
const num = (b: BigNumber) => b.toNumber();

/** Millionths in one whole: a tax rate of 8.25% is 82,500 ppm. */
export const PPM = 1_000_000;

/** A tax rate given as a percent (8.25), as millionths (82,500). Out of range reads as 0. */
export function ratePpm(ratePercent: number): number {
	if (!Number.isFinite(ratePercent) || ratePercent <= 0 || ratePercent > 100) return 0;
	return Math.round(ratePercent * 10_000);
}

/** Tax on a subtotal, half up, in whole minor units. Never negative, never above the subtotal. */
export function taxMinor(subtotal: number, ppm: number, inclusive: boolean): number {
	if (!Number.isSafeInteger(subtotal) || subtotal < 0) return 0;
	if (!Number.isSafeInteger(ppm) || ppm <= 0 || ppm > PPM) return 0;
	return num(core.TaxOn(big(subtotal), big(ppm), inclusive));
}

/** Subtotal + shipping + exclusive tax. Inclusive tax is inside the subtotal already. */
export function totalMinor(
	subtotal: number,
	shipping: number,
	tax: number,
	inclusive: boolean
): number {
	return num(core.Total(big(subtotal), big(shipping), big(tax), inclusive));
}

/** A base price at `percent` of itself (1..99), half up, not under `floor`; never above base. */
export function regionalUnitMinor(base: number, percent: number, floor: number): number {
	if (!Number.isSafeInteger(base) || base < 0) return base;
	if (!Number.isSafeInteger(percent)) return base;
	return num(core.RegionalUnit(big(base), big(percent), big(Math.max(0, Math.trunc(floor)))));
}

// ---- Currencies ----

/**
 * Currencies with no minor unit: an amount of 500 is ¥500, not ¥5.00. Stripe's list
 * (docs.stripe.com/currencies#zero-decimal).
 */
export const ZERO_DECIMAL_CURRENCIES: ReadonlySet<string> = new Set([
	'bif',
	'clp',
	'djf',
	'gnf',
	'jpy',
	'kmf',
	'krw',
	'mga',
	'pyg',
	'rwf',
	'ugx',
	'vnd',
	'vuv',
	'xaf',
	'xof',
	'xpf'
]);

/**
 * Currencies with three decimals. Stripe takes them in thousandths but only in whole tens (the
 * last digit must be 0), so 5.125 KWD cannot be charged and 5.120 can.
 */
export const THREE_DECIMAL_CURRENCIES: ReadonlySet<string> = new Set([
	'bhd',
	'jod',
	'kwd',
	'omr',
	'tnd'
]);

/** Digits after the decimal point in the currency's minor unit. */
export function currencyExponent(currency: string): 0 | 2 | 3 {
	const code = currency.toLowerCase();
	if (ZERO_DECIMAL_CURRENCIES.has(code)) return 0;
	if (THREE_DECIMAL_CURRENCIES.has(code)) return 3;
	return 2;
}

/** Stripe's largest amount for one charge: eight digits of minor units. */
export const STRIPE_MAX_AMOUNT = 99_999_999;

/**
 * Whether Stripe can be asked to charge `amount` minor units of `currency`. Not a price check (the
 * price was computed on the server); a shape check that keeps a request Stripe would refuse, or
 * worse misread, from being sent at all. Stripe's per-currency minimum charge is left to Stripe,
 * which refuses below it.
 */
export function isChargeableAmount(amount: number, currency: string): boolean {
	if (!Number.isSafeInteger(amount) || amount <= 0 || amount > STRIPE_MAX_AMOUNT) return false;
	if (!/^[a-z]{3}$/.test(currency)) return false;
	if (currencyExponent(currency) === 3 && amount % 10 !== 0) return false;
	return true;
}

// ---- The payment state machine ----

const STATUS_CODE: Record<OrderStatus, number> = {
	pending: 0,
	paid: 1,
	fulfilling: 2,
	shipped: 3,
	delivered: 4,
	cancelled: 5
};

export type PaymentEventKind = 'paying' | 'cancelling' | 'failed' | 'refunded' | 'other';
const KIND_CODE: Record<PaymentEventKind, number> = {
	paying: 0,
	cancelling: 1,
	failed: 2,
	refunded: 3,
	other: 4
};

export const PAYMENT_DECISIONS = [
	'ignore',
	'mark-paid',
	'already-paid',
	'cancel',
	'already-cancelled',
	'not-pending',
	'amount-mismatch',
	'paid-but-cancelled',
	'record',
	'not-paid'
] as const;
export type PaymentDecision = (typeof PAYMENT_DECISIONS)[number];

export interface PaymentFacts {
	status: OrderStatus;
	kind: PaymentEventKind;
	/** The event names this order and the payment reference this site recorded for it. */
	known: boolean;
	/** The provider says the money was taken. */
	moneyIn: boolean;
	/** What was taken, in minor units; null when the event does not say. */
	takenMinor: number | null;
	/** What the order costs, in minor units. */
	dueMinor: number;
	currencyMatches: boolean;
}

function args(f: PaymentFacts) {
	const taken = f.takenMinor;
	const hasAmount = typeof taken === 'number' && Number.isSafeInteger(taken);
	return [
		big(STATUS_CODE[f.status]),
		big(KIND_CODE[f.kind]),
		f.known,
		f.moneyIn,
		hasAmount,
		big(hasAmount ? (taken as number) : 0),
		big(f.dueMinor),
		f.currencyMatches
	] as const;
}

/** What a verified event means for an order (dafny/PaymentCore.dfy `Decide`). */
export function decidePaymentEvent(facts: PaymentFacts): PaymentDecision {
	return PAYMENT_DECISIONS[num(core.Decide(...args(facts)))];
}

const STATUS_OF = Object.fromEntries(
	Object.entries(STATUS_CODE).map(([name, code]) => [code, name])
) as Record<number, OrderStatus>;

/** The status the order should have after the event (dafny/PaymentCore.dfy `Step`). */
export function nextPaymentStatus(facts: PaymentFacts): OrderStatus {
	return STATUS_OF[num(core.Step(...args(facts)))];
}
